cmds=["diff","files","id","log","name","show","edit","fold","new","refresh","rename","spill","sync","email","export","next","patches","prev","series","top","branch","clean","commit","delete","float","goto","hide","import","init","pick","pop","pull","push","rebase","redo","repair","reset","sink","squash","uncommit","undo","unhide","completion","version"]
for c in cmds: add(c,[c])
for sub in ["bash","fish","zsh","list","man"]: add(f"completion {sub}",["completion",sub])
for sub in ["aliases","commands","commands-and-aliases"]: add(f"completion list {sub}",["completion","list",sub])
for sub in ["format","send"]: add(f"email {sub}",["email",sub])
# branch modes
modes={"list":"--list","create":"--create","clone":"--clone","rename":"--rename","protect":"--protect","unprotect":"--unprotect","delete":"--delete","cleanup":"--cleanup","describe":"--describe"}
for name,flag in modes.items(): add(f"branch {flag}",["branch",flag])
# aliases help via help command
aliases=["add","mv","resolved","rm","status"]
for a in aliases: add(f"alias:{a}",["help",a])

data={}
for key,args in specs:
    for kind,flag in [("long","--help"),("short","-h")]:
        if key=="main":
            p=subprocess.run([EXE,flag],capture_output=True,text=True)
        elif key.startswith("branch --"):
            p=subprocess.run([EXE]+args+[flag],capture_output=True,text=True)
        elif key.startswith("alias:"):
            # only long via help command; short is same? alias -h will delegate to git, so store help output as both? We'll handle alias help separately
            p=subprocess.run([EXE]+args,capture_output=True,text=True) if kind=="long" else None
            if p is None: continue
        else:
            p=subprocess.run([EXE]+args+[flag],capture_output=True,text=True)
        if p.returncode!=0:
            print("FAIL",key,flag,p.returncode,p.stderr[:200])
        data.setdefault(key,{})[kind]=p.stdout
    # also help command equivalent should equal long; verify for non-branch
# man pages and completions
os.makedirs("/tmp/captured",exist_ok=True)
for name,args in [("bash",["completion","bash"]),("fish",["completion","fish"]),("zsh",["completion","zsh"])]:
    p=subprocess.run([EXE]+args,capture_output=True,text=True)
    open(f"/tmp/captured/comp_{name}.txt","w").write(p.stdout)
for c in ["commands","aliases","commands-and-aliases"]:
    for s in ["name-only","asciidoc","fish","zsh"]:
        p=subprocess.run([EXE,"completion","list",c,"--style",s],capture_output=True,text=True)
        open(f"/tmp/captured/list_{c}_{s}.txt","w").write(p.stdout)
        p2=subprocess.run([EXE,"completion","list",c,"--style",s,"--show-expansion"],capture_output=True,text=True) if c=="aliases" else None
        if p2: open(f"/tmp/captured/list_{c}_{s}_exp.txt","w").write(p.stdout)  # placeholder
# man generation to tmp
import shutil, pathlib
if os.path.exists("/tmp/manout2"): shutil.rmtree("/tmp/manout2")
os.makedirs("/tmp/manout2")
subprocess.run([EXE,"completion","man","-o","/tmp/manout2"],capture_output=True,text=True)
man={}
for f in sorted(pathlib.Path("/tmp/manout2").glob("*.txt")):
    man[f.name]=f.read_text()
open("/tmp/captured/man.json","w").write(json.dumps(man))
open("/tmp/captured/help.json","w").write(json.dumps(data))
print("keys",len(data))
for k,v in data.items(): print(k, len(v.get("long","")), len(v.get("short","")))
