{"command":"cat > src/stg.py <<'PYEOF'
#!/usr/bin/env python3
# Stacked Git (StGit) compatible tool - original reimplementation from observed behaviour.
import sys, os, re, json, subprocess, tempfile, shutil, difflib, datetime, zlib, base64, shlex, stat

VERSION_LONG = """Stacked Git 2.5.5
Copyright (C) 2005-2025 StGit authors
This is free software: you are free to change and redistribute it.
There is NO WARRANTY, to the extent permitted by law.
SPDX-License-Identifier: GPL-2.0-only
"""
VERSION_SHORT = "stg 2.5.5\n"

DATA_BLOB = """
__DATA_BLOB__
"""

def _load_data():
    try:
        raw = zlib.decompress(base64.b85decode(DATA_BLOB.strip().encode()))
        return json.loads(raw.decode())
    except Exception:
        return {"help": {}, "comp": {}, "lists": {}, "man": {}}
DATA = _load_data()
HELP = DATA.get("help", {})

COLOR_MODE = "auto"  # auto, always, ansi, never

def color_enabled():
    if COLOR_MODE in ("always", "ansi"):
        return True
    if COLOR_MODE == "never":
        return False
    # auto
    if os.environ.get("NO_COLOR") is not None:
        return False
    try:
        return sys.stdout.isatty()
    except Exception:
        return False

def git_color_arg():
    if COLOR_MODE in ("always", "ansi"):
        return "always"
    if COLOR_MODE == "never":
        return "never"
    return "auto"

def out_text(s):
    if s:
        sys.stdout.buffer.write(s.encode() if isinstance(s, str) else s)
def err_text(s):
    if s:
        sys.stderr.buffer.write(s.encode() if isinstance(s, str) else s)

class StgError(Exception):
    def __init__(self, msg, code=2):
        super().__init__(msg)
        self.msg = msg
        self.code = code

class ClapError(Exception):
    def __init__(self, text):
        super().__init__(text)
        self.text = text

# ---------- generic subprocess helpers ----------
def run_cmd(args, input_data=None, cwd=None, env_extra=None, capture=True):
    env = dict(os.environ)
    if env_extra:
        env.update(env_extra)
    if capture:
        return subprocess.run(args, input=input_data, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env)
    else:
        return subprocess.run(args, input=input_data, cwd=cwd, env=env)

def git(args, input_data=None, env_extra=None, capture=True, cwd=None):
    return run_cmd(["git"] + args, input_data=input_data, cwd=cwd, env_extra=env_extra, capture=capture)

def git_ok(args, **kw):
    p = git(args, **kw)
    return p.returncode == 0

def git_out(args, input_data=None, env_extra=None):
    p = git(args, input_data=input_data, env_extra=env_extra)
    if p.returncode != 0:
        raise StgError(p.stderr.decode(errors="replace").strip() or p.stdout.decode(errors="replace").strip())
    return p.stdout

def decode(b):
    return b.decode(errors="surrogateescape") if isinstance(b, bytes) else b

# ---------- help handling ----------
def help_text(key, kind="long"):
    ent = HELP.get(key)
    if ent and kind in ent and ent[kind]:
        return ent[kind]
    if ent:
        return ent.get("long") or ent.get("short") or ""
    return ""

def usage_from_help(key, kind="short"):
    txt = help_text(key, kind) or help_text(key, "long")
    lines = txt.splitlines()
    usage = []
    in_u = False
    for ln in lines:
        if ln.startswith("Usage:"):
            in_u = True
            usage.append(ln)
            continue
        if in_u:
            if ln.strip() == "":
                break
            usage.append(ln)
    return "\n".join(usage)

def clap_error(msg, key=None, usage_key=None, tip=None, extra=None):
    # key for usage determination; usage_key overrides
    parts = []
    parts.append(f"error: {msg}\n")
    if tip:
        parts.append(f"\n  tip: {tip}\n")
    if extra:
        parts.append(f"{extra}\n" if extra.startswith("\n") or extra.startswith(" ") else f"\n{extra}\n")
        # extra already handled specially in some callers
    if key is not None:
        uk = usage_key or key
        u = usage_from_help(uk, "short")
        if u:
            parts.append(f"\n{u}\n")
    parts.append("\nFor more information, try '--help'.\n")
    txt = "".join(parts)
    # fix possible double blank from extra handling
    raise ClapError(txt)

def similar_subcommand(name, candidates):
    best = None
    best_ratio = 0.0
    for cand in candidates:
        # clap uses jaro-like; difflib approx is adequate for common cases
        r = difflib.SequenceMatcher(None, name, cand).ratio()
        # also boost prefix / substring similarity like bad->bash
        if cand.startswith(name) or name.startswith(cand):
            r = max(r, 0.85)
        if r > best_ratio:
            best_ratio = r
            best = cand
    if best and best_ratio >= 0.65:
        return best
    return None

# main command list in display order (patch inspection etc) and alpha list
COMMANDS = ["branch","clean","commit","completion","delete","diff","edit","email","export","files","float","fold","goto","hide","id","import","init","log","name","new","next","patches","pick","pop","prev","pull","push","rebase","redo","refresh","rename","repair","reset","series","show","sink","spill","squash","sync","top","uncommit","undo","unhide","version"]
BUILTIN_ALIASES = {
    "add": 'git -C "$GIT_PREFIX" add',
    "mv": 'git -C "$GIT_PREFIX" mv',
    "resolved": 'git -C "$GIT_PREFIX" add',
    "rm": 'git -C "$GIT_PREFIX" rm',
    "status": "git status -s",
}

def get_aliases():
    # returns ordered dict name->expansion string (without leading ! if shell, or stg command string)
    # custom aliases from git config stgit.alias.*
    aliases = {}
    # builtin first in defined order then will sort for display
    for k, v in BUILTIN_ALIASES.items():
        aliases[k] = ("shell", v)
    # git config may work even outside repo for global config
    try:
        p = git(["config", "--get-regexp", r"^stgit\.alias\."])
        if p.returncode == 0:
            for line in p.stdout.decode(errors="replace").splitlines():
                # key value
                m = re.match(r"stgit\.alias\.(\S+)\s+(.*)$", line)
                if m:
                    name, val = m.group(1), m.group(2)
                    # keys may be lowercased by git config; alias names are case-insensitive in config? keep as is
                    if val.startswith("!"):
                        aliases[name] = ("shell", val[1:])
                    else:
                        aliases[name] = ("stg", val)
    except Exception:
        pass
    return aliases

def alias_display_desc(kind_val):
    kind, val = kind_val
    if kind == "shell":
        return f"Alias for shell command `{val}`"
    else:
        return f"Alias for `stg {val}`"

def main_help_dynamic(kind="long"):
    # if custom aliases differ from builtin, regenerate alias section
    aliases = get_aliases()
    builtin_names = set(BUILTIN_ALIASES.keys())
    # HELP main text contains builtin aliases; if only builtin, return as-is
    if set(aliases.keys()) == builtin_names:
        return help_text("main", kind)
    base = help_text("main", kind)
    if not base:
        return base
    # replace Aliases section
    lines = base.splitlines(True)
    # find start of "Aliases:\n" and "Help:""
    start = None
    end = None
    for i, ln in enumerate(lines):
        if ln.strip() == "Aliases:":
            start = i
        if start is not None and ln.strip() == "Help:":
            end = i
            break
    if start is None or end is None:
        return base
    names = sorted(aliases.keys())
    width = max(len(n) for n in names) + 2
    new_section = ["Aliases:\n"]
    for n in names:
        desc = alias_display_desc(aliases[n])
        new_section.append(f"  {n:<{width}}{desc}\n")
    new_section.append("\n")
    return "".join(lines[:start] + new_section + lines[end:])

def print_help(key, kind="long"):
    if key == "main":
        txt = main_help_dynamic(kind)
    else:
        txt = help_text(key, kind)
    if txt:
        # colourised help for clap when requested
        if color_enabled():
            txt = colorize_help(txt)
        out_text(txt)

def colorize_help(txt):
    # approximate clap colouring: headings bold+underline, leading literals bold
    out_lines = []
    section = None
    for ln in txt.splitlines():
        if re.match(r"^(Usage|Options|Arguments|Commands|Help|Patch inspection commands|Patch manipulation commands|Stack inspection commands|Stack manipulation commands|Administration commands|Aliases|Refresh Options|Patch Edit Options|Selection Options|Select Options|Display Options|Source Options|Import Options|Message Options|Cover Letter Options|Format Options|Send Options|Sending Options|Other Options|Header Options|.* Options|.* Commands):$", ln.strip()) or ln.strip().endswith(" commands:"):
            out_lines.append(f"\x1b[1m\x1b[4m{ln}\x1b[0m")
            section = ln.strip()
            continue
        # Usage lines: bold first two words? clap bolds literal 'stg ...' command name
        if ln.startswith("Usage:"):
            # bold "Usage:" handled above? This line starts with Usage: but our heading regex only if endswith colon
            out_lines.append(ln)
            continue
        # Options/commands list items: bold flag/command token
