# ---------- generic subprocess helpers ----------
def run_cmd(args, input_data=None, cwd=None, env_extra=None, capture=True):
    env = dict(os.environ)
    if env_extra:
        env.update(env_extra)
    if capture:
        return subprocess.run(args, input=input_data, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env)
    else:
        return subprocess.run(args, input=input_data, cwd=cwd, env=env)

def git(args, input_data=None, env_extra=None, capture=True, cwd=None):
    return run_cmd(["git"] + args, input_data=input_data, cwd=cwd, env_extra=env_extra, capture=capture)

def git_ok(args, **kw):
    p = git(args, **kw)
    return p.returncode == 0

def git_out(args, input_data=None, env_extra=None):
    p = git(args, input_data=input_data, env_extra=env_extra)
    if p.returncode != 0:
        raise StgError(p.stderr.decode(errors="replace").strip() or p.stdout.decode(errors="replace").strip())
