    txt = help_text(key, kind) or help_text(key, "long")
    lines = txt.splitlines()
    usage = []
    in_u = False
    for ln in lines:
        if ln.startswith("Usage:"):
            in_u = True
            usage.append(ln)
            continue
        if in_u:
            if ln.strip() == "":
                break
            usage.append(ln)
    return "\n".join(usage)

def clap_error(msg, key=None, usage_key=None, tip=None, extra=None):
    # key for usage determination; usage_key overrides
    parts = []
    parts.append(f"error: {msg}\n")
    if tip:
        parts.append(f"\n  tip: {tip}\n")
    if extra:
        parts.append(f"{extra}\n" if extra.startswith("\n") or extra.startswith(" ") else f"\n{extra}\n")
        # extra already handled specially in some callers
    if key is not None:
        uk = usage_key or key
        u = usage_from_help(uk, "short")
        if u:
            parts.append(f"\n{u}\n")
    parts.append("\nFor more information, try '--help'.\n")
    txt = "".join(parts)
    # fix possible double blank from extra handling
    raise ClapError(txt)

def similar_subcommand(name, candidates):
    best = None
    best_ratio = 0.0
    for cand in candidates:
        # clap uses jaro-like; difflib approx is adequate for common cases
        r = difflib.SequenceMatcher(None, name, cand).ratio()
        # also boost prefix / substring similarity like bad->bash
        if cand.startswith(name) or name.startswith(cand):
            r = max(r, 0.85)
        if r > best_ratio:
            best_ratio = r
            best = cand
    if best and best_ratio >= 0.65:
        return best
    return None

