def get_aliases():
    # returns ordered dict name->expansion string (without leading ! if shell, or stg command string)
    # custom aliases from git config stgit.alias.*
    aliases = {}
    # builtin first in defined order then will sort for display
    for k, v in BUILTIN_ALIASES.items():
        aliases[k] = ("shell", v)
    # git config may work even outside repo for global config
    try:
        p = git(["config", "--get-regexp", r"^stgit\.alias\."])
        if p.returncode == 0:
            for line in p.stdout.decode(errors="replace").splitlines():
                # key value
                m = re.match(r"stgit\.alias\.(\S+)\s+(.*)$", line)
                if m:
                    name, val = m.group(1), m.group(2)
                    # keys may be lowercased by git config; alias names are case-insensitive in config? keep as is
                    if val.startswith("!"):
                        aliases[name] = ("shell", val[1:])
                    else:
                        aliases[name] = ("stg", val)
    except Exception:
        pass
    return aliases

def alias_display_desc(kind_val):
    kind, val = kind_val
    if kind == "shell":
        return f"Alias for shell command `{val}`"
    else:
        return f"Alias for `stg {val}`"

def main_help_dynamic(kind="long"):
    # if custom aliases differ from builtin, regenerate alias section
    aliases = get_aliases()
    builtin_names = set(BUILTIN_ALIASES.keys())
    # HELP main text contains builtin aliases; if only builtin, return as-is
    if set(aliases.keys()) == builtin_names:
        return help_text("main", kind)
    base = help_text("main", kind)
    if not base:
        return base
    # replace Aliases section
    lines = base.splitlines(True)
    # find start of "Aliases:\n" and "Help:""
    start = None
    end = None
    for i, ln in enumerate(lines):
        if ln.strip() == "Aliases:":
            start = i
        if start is not None and ln.strip() == "Help:":
            end = i
            break
    if start is None or end is None:
        return base
    names = sorted(aliases.keys())
    width = max(len(n) for n in names) + 2
    new_section = ["Aliases:\n"]
    for n in names:
        desc = alias_display_desc(aliases[n])
        new_section.append(f"  {n:<{width}}{desc}\n")
    new_section.append("\n")
    return "".join(lines[:start] + new_section + lines[end:])

def print_help(key, kind="long"):
    if key == "main":
        txt = main_help_dynamic(kind)
    else:
        txt = help_text(key, kind)
    if txt:
        # colourised help for clap when requested
        if color_enabled():
