def colorize_help(txt):
    # approximate clap colouring: headings bold+underline, leading literals bold
    out_lines = []
    section = None
    for ln in txt.splitlines():
        if re.match(r"^(Usage|Options|Arguments|Commands|Help|Patch inspection commands|Patch manipulation commands|Stack inspection commands|Stack manipulation commands|Administration commands|Aliases|Refresh Options|Patch Edit Options|Selection Options|Select Options|Display Options|Source Options|Import Options|Message Options|Cover Letter Options|Format Options|Send Options|Sending Options|Other Options|Header Options|.* Options|.* Commands):$", ln.strip()) or ln.strip().endswith(" commands:"):
            out_lines.append(f"\x1b[1m\x1b[4m{ln}\x1b[0m")
            section = ln.strip()
            continue
        # Usage lines: bold first two words? clap bolds literal 'stg ...' command name
        if ln.startswith("Usage:"):
            # bold "Usage:" handled above? This line starts with Usage: but our heading regex only if endswith colon
            out_lines.append(ln)
            continue
        # Options/commands list items: bold flag/command token
        m = re.match(r"^(\s{2,})((?:-[A-Za-z],\s*)?--[A-Za-z0-9_-]+|-[A-Za-z]|--[A-Za-z0-9_-]+|[A-Za-z][A-Za-z0-9_-]*)(\s.*|)$", ln)
        if m and (section and ("Option" in section or "Commands" in section or section in ("Help:", "Aliases:"))):
            out_lines.append(f"{m.group(1)}\x1b[1m{m.group(2)}\x1b[0m{m.group(3)}")
            continue
        out_lines.append(ln)
    return "\n".join(out_lines) + ("\n" if txt.endswith("\n") else "")

