        pb = git(["symbolic-ref", "HEAD"])
        if pb.returncode != 0:
            self.branch = None
            self.head_ref = None
        else:
            ref = pb.stdout.decode().strip()
            self.head_ref = ref
            if ref.startswith("refs/heads/"):
                self.branch = ref[len("refs/heads/"):]
            else:
                self.branch = ref
        # head oid
        ph = git(["rev-parse", "HEAD"])
        if ph.returncode != 0:
            # unborn
            if self.branch:
                raise StgError(f"branch `refs/heads/{self.branch}` is unborn")
            raise StgError("HEAD is not a symbolic ref" if False else "not on branch, HEAD is detached")
        self.head = ph.stdout.decode().strip()

