        if not self.branch or not self.head_ref or not self.head_ref.startswith("refs/heads/"):
            raise StgError("not on branch, HEAD is detached")
        return self.branch

    def refresh_head(self):
        ph = git(["rev-parse", "HEAD"])
        if ph.returncode == 0:
            self.head = ph.stdout.decode().strip()

    def ref_oid(self, ref):
        p = git(["show-ref", "--verify", ref])
        if p.returncode != 0:
            return None
        return p.stdout.decode().split()[0]

    def update_ref(self, ref, oid, msg=None):
        args = ["update-ref"]
        if msg is not None:
            args += ["-m", msg]
        args += [ref, oid]
        p = git(args)
        if p.returncode != 0:
            raise StgError(p.stderr.decode(errors="replace").strip())

    def delete_ref(self, ref):
        git(["update-ref", "-d", ref])

    def commit_info(self, oid):
        if oid is None:
            return None
        p = git(["cat-file", "commit", oid])
        if p.returncode != 0:
            raise StgError(f"object `{oid}` does not exist" if False else f"invalid committish `{oid}`")
        raw = p.stdout
        # split headers/message
        idx = raw.find(b"\n\n")
        headers = raw[:idx].decode(errors="surrogateescape") if idx >= 0 else raw.decode(errors="surrogateescape")
        message = raw[idx+2:] if idx >= 0 else b""
        tree = None
        parents = []
        author = None
        committer = None
        for line in headers.splitlines():
            if line.startswith("tree "):
                tree = line[5:].strip()
            elif line.startswith("parent "):
                parents.append(line[7:].strip())
            elif line.startswith("author "):
                author = line[7:].strip()
            elif line.startswith("committer "):
                committer = line[10:].strip()
        return {"oid": oid, "tree": tree, "parents": parents, "author": author, "committer": committer, "message": message}

    def parse_ident(self, ident):
        # "Name <email> timestamp tz"
        if not ident:
            return ("", "", 0, "+0000")
        m = re.match(r"^(.*) <(.*)> (\d+) ([+-]\d{4})$", ident)
        if not m:
            # fallback
            m2 = re.match(r"^(.*) <(.*)>", ident)
            if m2:
