            name, email, ts, tz = author_ident
            env["GIT_AUTHOR_NAME"] = name
            env["GIT_AUTHOR_EMAIL"] = email
            env["GIT_AUTHOR_DATE"] = f"{ts} {tz}"
            if committer_date_is_author:
                env["GIT_COMMITTER_DATE"] = f"{ts} {tz}"
        elif committer_date_is_author:
