            pass
        if isinstance(message, str):
            message = message.encode()
        p = git(args, input_data=message, env_extra=env)
        if p.returncode != 0:
            raise StgError(p.stderr.decode(errors="replace").strip())
        return p.stdout.decode().strip()

    def committer_ident(self):
        # obtain default committer identity via git var
        p = git(["var", "GIT_COMMITTER_IDENT"])
        if p.returncode == 0:
            return self.parse_ident(p.stdout.decode().strip())
        # fallback config
        name = git(["config", "user.name"]).stdout.decode().strip()
        email = git(["config", "user.email"]).stdout.decode().strip()
        return (name, email, int(datetime.datetime.now().timestamp()), "+0000")

    def author_ident_default(self):
        p = git(["var", "GIT_AUTHOR_IDENT"])
        if p.returncode == 0:
            return self.parse_ident(p.stdout.decode().strip())
        return self.committer_ident()

    def format_date(self, ts, tz):
        # tz like +0000
        sign = 1
        if tz.startswith("-"):
            sign = -1
        try:
            hh = int(tz[1:3]); mm = int(tz[3:5])
        except Exception:
            hh = mm = 0
        offset = datetime.timezone(sign * datetime.timedelta(hours=hh, minutes=mm))
        dt = datetime.datetime.fromtimestamp(ts, tz=offset)
        return dt.strftime("%Y-%m-%d %H:%M:%S ") + tz

