                    with open(fpath, "rb") as fh:
                        data = fh.read()
                    blob = repo.create_blob(data)
                    # mode: prefer stage2 mode else stage3 else 100644
                    mode = "100644"
                    for s, md, o in stages[path]:
                        if s == 2:
                            mode = md; break
                    # add to index
                    g(["update-index", "--add", "--cacheinfo", f"{mode},{blob},{path}"])
                    marker_blobs[path] = data
                else:
                    # deleted in worktree: keep stage2 if present
                    for s, md, o in stages[path]:
                        if s == 2:
                            g(["update-index", "--add", "--cacheinfo", f"{md},{o},{path}"])
                            break
            wt = g(["write-tree"])
            tree = wt.stdout.decode().strip() if wt.returncode == 0 else repo.tree_of(theirs_commit)
            return (tree, conflicts, stages, marker_blobs)
        else:
            wt = g(["write-tree"])
            if wt.returncode != 0:
                return (None, [], None, None)
            return (wt.stdout.decode().strip(), [], None, None)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)

# ---------- printing ----------
class Printer:
    def __init__(self):
        self.printed_top_names = set()
        self.any_printed = False
    def raw(self, line):
        self.any_printed = True
        if color_enabled():
            out_text(colorize_status_line(line))
        else:
            out_text(line + "\n")
    def status(self, symbol, name, suffix=""):
        # symbol one char, name may be range
        line = f"{symbol} {name}{suffix}"
        if symbol == ">":
            # extract base name for range? top is single
            self.printed_top_names.add(name)
        self.raw(line)
    def rename_line(self, old, new):
        self.raw(f"{old} => {new}")

def colorize_status_line(line):
    # line formats: "<sym> <name><suffix>" or "old => new" or ...
    m = re.match(r"^([+>\-!#&$@\?]) (.+)$", line)
    if not m:
        # rename
        m2 = re.match(r"^(.+) => (.+)$", line)
        if m2:
            return line  # unk colours
        return line
    sym, rest = m.group(1), m.group(2)
    # split suffix starting with " ("
    suffix = ""
    name = rest
    if " (" in rest:
        name, suf = rest.split(" (", 1)
        suffix = " (" + suf
    colors = {"+": "32", ">": "34", "-": "35", "!": "31", "#": "31", "&": "33", "$": "33", "@": "31"}
    c = colors.get(sym, "0")
    # name style
    if sym == ">":
        name_part = f"\x1b[0m\x1b[1m{name}\x1b[0m"
    elif sym == "-":
        name_part = f"\x1b[0m\x1b[2m{name}\x1b[0m"
    elif sym in ("!", "#"):
        name_part = f"\x1b[0m\x1b[2m{name}\x1b[0m"
    else:
        name_part = f"\x1b[0m{name}\x1b[0m"
    return f"\x1b[0m\x1b[{c}m{sym} \x1b[0m{name_part}{suffix}"

# ---------- transaction / checkout ----------
def worktree_is_clean(repo):
    # tracked changes only
    p = git(["status", "--porcelain=v1", "-uno"])
    if p.returncode != 0:
        return True
    return p.stdout.strip() == b""

def save_local_changes(repo):
    # returns (staged_patch_bytes, worktree_patch_bytes)
    staged = git(["diff", "--cached", "--binary", "HEAD"]).stdout if git(["rev-parse", "HEAD"]).returncode == 0 else b""
    work = git(["diff", "--binary"]).stdout
    return (staged, work)

def apply_local_changes(repo, staged, work):
    ok = True
    if staged:
        p = git(["apply", "--cached", "--binary"], input_data=staged)
        if p.returncode != 0:
            ok = False
    if work:
        p = git(["apply", "--binary"], input_data=work)
        if p.returncode != 0:
            # try 3way?
            p2 = git(["apply", "--3way", "--binary"], input_data=work)
            if p2.returncode != 0:
                ok = False
    return ok

def checkout_new_head(repo, old_head, new_head, log_msg, hard=False, keep=False, branch=None):
    branch = branch or repo.branch
    if branch != repo.branch:
        # only update other branch ref
        if new_head and old_head != new_head:
            repo.update_ref(f"refs/heads/{branch}", new_head, msg=log_msg)
        return
    if old_head == new_head:
        return
    if hard:
        repo.update_ref(f"refs/heads/{branch}", new_head, msg=log_msg)
        git(["reset", "--hard", "-q"])
        return
    if keep:
        staged, work = save_local_changes(repo)
        repo.update_ref(f"refs/heads/{branch}", new_head, msg=log_msg)
        git(["reset", "--hard", "-q"])
        apply_local_changes(repo, staged, work)
        return
    # if clean, just reset hard; if dirty but head change is being done by a command that allowed dirty (e.g. undo, rename of etc where head changes to same tree? ) preserve
    if worktree_is_clean(repo):
        repo.update_ref(f"refs/heads/{branch}", new_head, msg=log_msg)
        git(["reset", "--hard", "-q"])
    else:
        staged, work = save_local_changes(repo)
        repo.update_ref(f"refs/heads/{branch}", new_head, msg=log_msg)
        git(["reset", "--hard", "-q"])
        apply_local_changes(repo, staged, work)

class Transaction:
    def __init__(self, repo, stack, printer=None, allow_conflicts=True):
        self.repo = repo
        self.stack = stack
        self.printer = printer or Printer()
        self.old_head = stack.head
        self.allow_conflicts = allow_conflicts

    def commit(self, new_state, log_msg, hard=False, keep=False, suppress_top=False, prev_override=None, simple_parent_override=None, clear_log=False):
        repo = self.repo
        stack = self.stack
        # build patches blobs
        patches = new_state["patches"]
        blobs = {}
        old_blobs = stack.blobs
        old_patches = stack.patches
        for name, oid in patches.items():
            if name in old_patches and old_patches[name] == oid and name in old_blobs:
                blobs[name] = old_blobs[name]
            elif name in new_state.get("blobs", {}) and name in old_blobs and old_patches.get(name) == oid:
                blobs[name] = new_state["blobs"][name]
            else:
                # if blob provided in new_state explicitly
                if "blobs" in new_state and name in new_state["blobs"] and (name not in old_patches or old_patches.get(name) != oid or True) and False:
                    blobs[name] = new_state["blobs"][name]
                else:
                    # check if renamed: blob from old name with same oid
                    found = None
                    for on, ooid in old_patches.items():
                        if ooid == oid and on in old_blobs:
                            found = old_blobs[on]
                            break
                    if found is not None and name not in old_patches:
                        blobs[name] = found
                    else:
                        blobs[name] = patch_blob_bytes(repo, oid)
        # stack.json
        if clear_log:
            prev_val = None
        else:
            prev_val = prev_override if prev_override is not None else stack.full_oid
        json_obj = {
            "version": 5,
            "prev": prev_val,
            "head": new_state["head"],
            "applied": new_state["applied"],
            "unapplied": new_state["unapplied"],
            "hidden": new_state["hidden"],
            "patches": {name: {"oid": patches[name]} for name in sorted(patches.keys())},
        }
        json_str = json.dumps(json_obj, indent=2)
        # write tree via temp index
        tmpdir = tempfile.mkdtemp(prefix="stg-stack-")
        try:
            index_file = os.path.join(tmpdir, "index")
            env = {"GIT_INDEX_FILE": index_file}
            def g(args, inp=None):
                return run_cmd(["git"] + args, input_data=inp, env_extra=env)
            g(["read-tree", "--empty"])
            # stack.json blob
            blob_oid = repo.create_blob(json_str.encode())
            g(["update-index", "--add", "--cacheinfo", f"100644,{blob_oid},stack.json"])
            for name in sorted(patches.keys()):
                boid = repo.create_blob(blobs[name])
                g(["update-index", "--add", "--cacheinfo", f"100644,{boid},patches/{name}"])
            wt = g(["write-tree"])
            tree_oid = wt.stdout.decode().strip()
        finally:
            shutil.rmtree(tmpdir, ignore_errors=True)
        # simplified commit
        if clear_log:
            simple_parent = None
        else:
            simple_parent = simple_parent_override if simple_parent_override is not None else stack.simple_oid
        simple_parents = [simple_parent] if simple_parent else []
        simple_oid = repo.create_commit(tree_oid, simple_parents, log_msg)
        # full commit parents: simple, head (if not ancestor of prev), prev
        parents = [simple_oid]
        head_oid = new_state["head"]
        prev_full = prev_val if not clear_log else stack.full_oid if False else None
        # original: prev is stored in json; for clear, no prev parent? keep simple
        actual_prev_full = stack.full_oid if not clear_log else None
        if head_oid:
            # check ancestor of actual_prev_full
            include_head = True
            if actual_prev_full:
                # if head is ancestor of prev_full, skip
                if git_ok(["merge-base", "--is-ancestor", head_oid, actual_prev_full]):
                    include_head = False
            if include_head:
                parents.append(head_oid)
        if actual_prev_full:
            parents.append(actual_prev_full)
        full_oid = repo.create_commit(tree_oid, parents, log_msg)
        # update refs
        # head checkout first? Stack ref update after ?
        old_head = stack.head
        # update patch refs
        for name, oid in patches.items():
            ref = f"refs/patches/{stack.branch}/{name}"
            cur = repo.ref_oid(ref)
            if cur != oid:
                repo.update_ref(ref, oid)
        for name in list(old_patches.keys()):
            if name not in patches:
                repo.delete_ref(f"refs/patches/{stack.branch}/{name}")
        # stack ref
        repo.update_ref(f"refs/stacks/{stack.branch}", full_oid)
        # branch head
        checkout_new_head(repo, old_head, new_state["head"], log_msg, hard=hard, keep=keep, branch=stack.branch)
        # update stack object in memory
        stack.full_oid = full_oid
        stack.simple_oid = simple_oid
        stack.initialized = True
        stack.set_from_state({**new_state, "blobs": blobs})
        stack.prev = prev_val
        repo.refresh_head()
        # final top printing
        if not suppress_top:
            top = stack.top()
            if top and top not in self.printer.printed_top_names:
                self.printer.status(">", top)
        return full_oid

def ensure_stack(repo, stack, printer=None):
    """If stack not initialized, create initialize transaction"""
    if stack.initialized:
        return
    # check branch unborn already handled by Repo
    branch = repo.require_branch()
    # initial state
    state = {"head": repo.head, "applied": [], "unapplied": [], "hidden": [], "patches": {}, "blobs": {}}
    # temporary Stack's full is None
    tx = Transaction(repo, stack, printer=printer or Printer())
    # suppress top (no patches)
    tx.commit(state, "initialize", suppress_top=True)
    # stack now initialized

def require_stack(repo, stack):
    if not stack.initialized:
        raise StgError(f"StGit stack not initialized for branch `{stack.branch}`")

# utilities for patch selection / ranges
def canonical_order(stack):
    return stack.applied + stack.unapplied + stack.hidden

def resolve_patch_names(stack, args, allow_ranges=True, must_exist=True):
    result = []
    order = canonical_order(stack)
    for a in args:
        if allow_ranges and ".." in a:
            # range a..b where either may be empty?
            if a.startswith("..") or a.endswith("..") or ".." in a:
                parts = a.split("..")
                if len(parts) == 2:
                    start, end = parts
                    # handle forms like p1..p2
                    if start == "" and end == "":
                        raise StgError(f"patch `{a}` does not exist")
                    if start == "":
                        start_name = order[0] if order else None
                    else:
                        start_name = start
                    if end == "":
                        end_name = order[-1] if order else None
                    else:
                        end_name = end
                    if must_exist:
                        if start_name not in stack.patches:
                            raise StgError(f"patch `{start_name}` does not exist")
                        if end_name not in stack.patches:
                            raise StgError(f"patch `{end_name}` does not exist")
                    try:
                        i1 = order.index(start_name); i2 = order.index(end_name)
                    except ValueError:
                        raise StgError(f"patch `{a}` does not exist")
                    if i1 <= i2:
                        rng = order[i1:i2+1]
                    else:
                        rng = list(reversed(order[i2:i1+1]))
                    for n in rng:
                        if n not in result:
                            result.append(n)
                    continue
        name = a
        # escaped leading dash \-
        if name.startswith("\\-"):
            name = name[1:]
        if must_exist and name not in stack.patches:
            raise StgError(f"patch `{name}` does not exist")
        if name not in result:
            result.append(name)
    return result

