# ---------- stack state ----------
class Stack:
    def __init__(self, repo, branch=None):
        self.repo = repo
        self.branch = branch if branch is not None else repo.branch
        self.initialized = False
        self.full_oid = None
        self.simple_oid = None
        self.head = repo.head if self.branch == repo.branch else None
        self.applied = []
        self.unapplied = []
        self.hidden = []
        self.patches = {}  # name -> oid
        self.blobs = {}  # name -> bytes
        self.prev = None
        if self.branch is None:
            return
        ref = f"refs/stacks/{self.branch}"
        oid = repo.ref_oid(ref)
        if oid is None:
            # head defaults to branch head
            br_oid = repo.ref_oid(f"refs/heads/{self.branch}")
            if br_oid:
                self.head = br_oid
            return
        self.initialized = True
        self.full_oid = oid
        info = repo.commit_info(oid)
        self.simple_oid = info["parents"][0] if info["parents"] else None
        # read stack.json
        p = git(["cat-file", "-p", f"{oid}^{{tree}}:stack.json"])
        if p.returncode != 0:
            raise StgError(f"stack for branch `{self.branch}` is corrupt")
        try:
            data = json.loads(p.stdout.decode())
        except Exception:
            raise StgError(f"stack for branch `{self.branch}` is corrupt")
        self.prev = data.get("prev")
        self.head = data.get("head")
        self.applied = list(data.get("applied", []))
        self.unapplied = list(data.get("unapplied", []))
        self.hidden = list(data.get("hidden", []))
        patches = data.get("patches", {})
        for name in patches:
            self.patches[name] = patches[name].get("oid")
        # blobs
        # list tree
        pt = git(["ls-tree", f"{oid}^{{tree}}", "patches/"])
        # alternative: ls-tree -r
        pt = git(["ls-tree", "-r", info["tree"]])
        if pt.returncode == 0:
            for line in pt.stdout.decode(errors="surrogateescape").splitlines():
                # mode type oid\tpath
                m = re.match(r"\d+ blob ([0-9a-f]+)\t(.+)$", line)
                if m and m.group(2).startswith("patches/"):
                    name = m.group(2)[len("patches/"):]
                    bp = git(["cat-file", "-p", m.group(1)])
                    if bp.returncode == 0:
                        self.blobs[name] = bp.stdout

    def all_names(self):
        return self.applied + self.unapplied + self.hidden

    def exists(self, name):
        return name in self.patches

    def status_of(self, name):
        if name in self.applied:
            return "applied"
        if name in self.unapplied:
            return "unapplied"
        if name in self.hidden:
            return "hidden"
        return None

    def base_oid(self):
        if self.applied:
            info = self.repo.commit_info(self.patches[self.applied[0]])
            if info and info["parents"]:
                return info["parents"][0]
            return None
        return self.head

    def top(self):
        return self.applied[-1] if self.applied else None

    def patch_info(self, name):
        if name not in self.patches:
            raise StgError(f"patch `{name}` does not exist")
        return self.repo.commit_info(self.patches[name])

    def is_empty_patch(self, name):
        info = self.patch_info(name)
        if not info["parents"]:
            return info["tree"] == EMPTY_TREE
        parent_tree = self.repo.tree_of(info["parents"][0])
        return info["tree"] == parent_tree

    def clone_state(self):
        return {
            "head": self.head,
            "applied": list(self.applied),
            "unapplied": list(self.unapplied),
            "hidden": list(self.hidden),
            "patches": dict(self.patches),
            "blobs": dict(self.blobs),
        }

    def set_from_state(self, st):
        self.head = st["head"]
        self.applied = list(st["applied"])
        self.unapplied = list(st["unapplied"])
        self.hidden = list(st["hidden"])
        self.patches = dict(st["patches"])
        if "blobs" in st:
            self.blobs = dict(st["blobs"])

def patch_blob_bytes(repo, patch_oid):
    info = repo.commit_info(patch_oid)
    if info["parents"]:
        bottom = repo.tree_of(info["parents"][0])
    else:
        bottom = EMPTY_TREE
    top = info["tree"]
    an, ae, ats, atz = repo.parse_ident(info["author"])
    cn, ce, cts, ctz = repo.parse_ident(info["committer"])
    author_str = f"{an} <{ae}>"
    date_str = repo.format_date(cts, ctz)
    header = f"Bottom: {bottom}\nTop:    {top}\nAuthor: {author_str}\nDate:   {date_str}\n\n".encode()
    return header + info["message"]

# ---------- merge helpers ----------
def merge_patch_onto(repo, patch_oid, new_parent_oid, committer_date_is_author=False, set_tree=False):
    """return (new_oid, new_tree, conflicts[list], conflict_stage_data or None)
       If patch parent already == new_parent, return original oid.
    """
    info = repo.commit_info(patch_oid)
    old_parent = info["parents"][0] if info["parents"] else None
    if old_parent == new_parent_oid and not set_tree:
        return (patch_oid, info["tree"], [], None)
    if set_tree:
        merged_tree = info["tree"]
        # create new commit with same tree but new parent
        an, ae, ats, atz = repo.parse_ident(info["author"])
        new_oid = repo.create_commit(merged_tree, [new_parent_oid] if new_parent_oid else [], info["message"], author_ident=(an, ae, ats, atz), committer_date_is_author=committer_date_is_author)
        return (new_oid, merged_tree, [], None)
    # three-way merge
    if old_parent is None:
        # patch is root commit; its tree vs new parent: use empty as base
        base_oid_for_merge = EMPTY_TREE
        # merge-recursive needs a commit-ish? use new_parent as base <?> fall through to tree merge via diff apply?
        # treat old parent tree as empty: merging patch tree onto new parent where patch added all files
        # use merge-recursive with new_parent as base will lose? Use empty tree commit trick: create temporary orphan commit with empty tree?
        # Simpler: if new_parent tree == patch tree etc handled below by generic
        pass
    merged_tree, conflicts, stage_data, marker_blobs = three_way_merge_trees(repo, old_parent, new_parent_oid, patch_oid)
    if merged_tree is None and not conflicts:
        # fallback to patch tree
        merged_tree = info["tree"]
    an, ae, ats, atz = repo.parse_ident(info["author"])
    new_oid = repo.create_commit(merged_tree, [new_parent_oid] if new_parent_oid else [], info["message"], author_ident=(an, ae, ats, atz), committer_date_is_author=committer_date_is_author)
    return (new_oid, merged_tree, conflicts, (stage_data, marker_blobs) if conflicts else None)

def three_way_merge_trees(repo, base_commit, ours_commit, theirs_commit):
    """merge theirs onto ours with base. Returns (tree, conflicts, stage_data, marker_blobs)"""
    if base_commit == ours_commit:
        return (repo.tree_of(theirs_commit), [], None, None)
    if base_commit == theirs_commit:
        return (repo.tree_of(ours_commit), [], None, None)
    # if patch tree == base tree (empty patch) -> ours tree
    if repo.tree_of(theirs_commit) == (repo.tree_of(base_commit) if base_commit else EMPTY_TREE):
        return (repo.tree_of(ours_commit), [], None, None)
    if repo.tree_of(ours_commit) == (repo.tree_of(base_commit) if base_commit else EMPTY_TREE):
        return (repo.tree_of(theirs_commit), [], None, None)
    tmpdir = tempfile.mkdtemp(prefix="stg-merge-")
    try:
        workdir = os.path.join(tmpdir, "work")
        os.makedirs(workdir, exist_ok=True)
        index_file = os.path.join(tmpdir, "index")
        env = {"GIT_INDEX_FILE": index_file, "GIT_DIR": repo.gitdir, "GIT_WORK_TREE": workdir}
        def g(args, inp=None):
            return run_cmd(["git"] + args, input_data=inp, cwd=workdir, env_extra=env)
        # init index with ours
        p = g(["read-tree", ours_commit])
        if p.returncode != 0:
            return (None, [], None, None)
        base_arg = base_commit if base_commit else EMPTY_TREE
        p = g(["merge-recursive", base_arg, "--", ours_commit, theirs_commit])
        # collect ls-files -s
        ls = g(["ls-files", "-s"])
        stages = {}
        for line in ls.stdout.decode(errors="surrogateescape").splitlines():
            m = re.match(r"(\d+) ([0-9a-f]+) (\d+)\t(.+)$", line)
            if m:
                mode, oid, stage, path = m.group(1), m.group(2), int(m.group(3)), m.group(4)
                stages.setdefault(path, []).append((stage, mode, oid))
        conflicts = [path for path, entries in stages.items() if any(s != 0 for s, _, _ in entries)]
        marker_blobs = {}
        if conflicts:
            # build a tree resolving conflicts to marker file content (worktree file) if present
            for path in conflicts:
                # remove all stages for path
                g(["update-index", "--force-remove", "--", path])
                fpath = os.path.join(workdir, path)
                if os.path.isfile(fpath):
                    with open(fpath, "rb") as fh:
                        data = fh.read()
                    blob = repo.create_blob(data)
                    # mode: prefer stage2 mode else stage3 else 100644
                    mode = "100644"
                    for s, md, o in stages[path]:
                        if s == 2:
                            mode = md; break
                    # add to index
                    g(["update-index", "--add", "--cacheinfo", f"{mode},{blob},{path}"])
                    marker_blobs[path] = data
                else:
                    # deleted in worktree: keep stage2 if present
                    for s, md, o in stages[path]:
                        if s == 2:
                            g(["update-index", "--add", "--cacheinfo", f"{md},{o},{path}"])
                            break
            wt = g(["write-tree"])
            tree = wt.stdout.decode().strip() if wt.returncode == 0 else repo.tree_of(theirs_commit)
            return (tree, conflicts, stages, marker_blobs)
        else:
            wt = g(["write-tree"])
            if wt.returncode != 0:
                return (None, [], None, None)
            return (wt.stdout.decode().strip(), [], None, None)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)

# ---------- printing ----------
class Printer:
    def __init__(self):
        self.printed_top_names = set()
        self.any_printed = False
    def raw(self, line):
        self.any_printed = True
        if color_enabled():
            out_text(colorize_status_line(line))
        else:
            out_text(line + "\n")
    def status(self, symbol, name, suffix=""):
        # symbol one char, name may be range
        line = f"{symbol} {name}{suffix}"
        if symbol == ">":
            # extract base name for range? top is single
            self.printed_top_names.add(name)
        self.raw(line)
    def rename_line(self, old, new):
        self.raw(f"{old} => {new}")

def colorize_status_line(line):
    # line formats: "<sym> <name><suffix>" or "old => new" or ...
    m = re.match(r"^([+>\-!#&$@\?]) (.+)$", line)
    if not m:
        # rename
        m2 = re.match(r"^(.+) => (.+)$", line)
        if m2:
            return line  # unk colours
        return line
    sym, rest = m.group(1), m.group(2)
    # split suffix starting with " ("
    suffix = ""
    name = rest
    if " (" in rest:
        name, suf = rest.split(" (", 1)
        suffix = " (" + suf
    colors = {"+": "32", ">": "34", "-": "35", "!": "31", "#": "31", "&": "33", "$": "33", "@": "31"}
    c = colors.get(sym, "0")
    # name style
    if sym == ">":
        name_part = f"\x1b[0m\x1b[1m{name}\x1b[0m"
    elif sym == "-":
        name_part = f"\x1b[0m\x1b[2m{name}\x1b[0m"
    elif sym in ("!", "#"):
        name_part = f"\x1b[0m\x1b[2m{name}\x1b[0m"
    else:
        name_part = f"\x1b[0m{name}\x1b[0m"
    return f"\x1b[0m\x1b[{c}m{sym} \x1b[0m{name_part}{suffix}"

