def checkout_new_head(repo, old_head, new_head, log_msg, hard=False, keep=False, branch=None):
    branch = branch or repo.branch
    if branch != repo.branch:
        # only update other branch ref
        if new_head and old_head != new_head:
            repo.update_ref(f"refs/heads/{branch}", new_head, msg=log_msg)
