# utilities for patch selection / ranges
def canonical_order(stack):
    return stack.applied + stack.unapplied + stack.hidden

def resolve_patch_names(stack, args, allow_ranges=True, must_exist=True):
    result = []
    order = canonical_order(stack)
    for a in args:
        if allow_ranges and ".." in a:
            # range a..b where either may be empty?
            if a.startswith("..") or a.endswith("..") or ".." in a:
                parts = a.split("..")
                if len(parts) == 2:
                    start, end = parts
                    # handle forms like p1..p2
                    if start == "" and end == "":
                        raise StgError(f"patch `{a}` does not exist")
                    if start == "":
                        start_name = order[0] if order else None
                    else:
                        start_name = start
                    if end == "":
                        end_name = order[-1] if order else None
                    else:
                        end_name = end
                    if must_exist:
                        if start_name not in stack.patches:
                            raise StgError(f"patch `{start_name}` does not exist")
                        if end_name not in stack.patches:
                            raise StgError(f"patch `{end_name}` does not exist")
                    try:
                        i1 = order.index(start_name); i2 = order.index(end_name)
                    except ValueError:
                        raise StgError(f"patch `{a}` does not exist")
                    if i1 <= i2:
                        rng = order[i1:i2+1]
                    else:
                        rng = list(reversed(order[i2:i1+1]))
                    for n in rng:
                        if n not in result:
                            result.append(n)
                    continue
        name = a
        # escaped leading dash \-
        if name.startswith("\\-"):
            name = name[1:]
        if must_exist and name not in stack.patches:
            raise StgError(f"patch `{name}` does not exist")
        if name not in result:
            result.append(name)
    return result

