# ---------- revision resolution ----------
def load_repo_stack(branch=None, branch_opt=None):
    repo = Repo()
    b = branch_opt if branch_opt is not None else branch
    if b is not None:
        # validate branch exists if it's for stack selection (some callers handle)
        if repo.ref_oid(f"refs/heads/{b}") is None:
            raise StgError(f"branch `{b}` not found")
        stack = Stack(repo, branch=b)
    else:
        if repo.branch is None:
            # detached etc: let caller decide; many commands raise not on branch
            # mimic: raise for stack commands
            raise StgError("not on branch, HEAD is detached")
        stack = Stack(repo, branch=repo.branch)
    return repo, stack

def resolve_revision(repo, stack, rev, branch_opt=None):
