    # branch:patch form
    if ":" in rev:
        branch_part, rest = rev.split(":", 1)
        if branch_part == "" or rest == "":
            # clap invalid value
            caret_pos = rev.find(":")
            raise ClapError(f"error: invalid value '{rev}' for '[revision]': invalid StGit revision `{rev}`: {rev}\n  {' ' * caret_pos}^\n\n\nFor more information, try '--help'.\n")
