        if repo.ref_oid(f"refs/heads/{branch_part}") is None:
            if branch_part in ("HEAD", "FETCH_HEAD") or "/" in branch_part or branch_part.startswith("refs/"):
                raise StgError(f"reference `{branch_part}` is not a local branch")
            raise StgError(f"branch `{branch_part}` not found")
        other_stack = Stack(repo, branch=branch_part)
        return resolve_revision(repo, other_stack, rest, branch_opt=None)
    if rev == "{base}":
