def patch_range_expand(stack, arg, order=None, reverse_error=False, for_show=False):
    """Expand a range arg if it contains .. and both ends are patches/indices etc, else return [arg]"""
    if ".." not in arg:
        return [arg]
    if arg.count("..") != 1:
        # invalid handled elsewhere
        return [arg]
    start, end = arg.split("..", 1)
    order = order or canonical_order(stack)
