def cmd_name(args):
    parsed = parse_args("name", args, [opt("branch", "b", "branch", "value", "--branch <branch>"), opt("showbranch", None, "showbranch")], pos_name="[revision]", pos_max=1, allow_hyphen=True)
    repo, stack = load_repo_stack(branch_opt=get_opt(parsed, "branch"))
    require_stack(repo, stack)
    rev = parsed.pos[0] if parsed.pos else None
    oid = resolve_revision(repo, stack, rev)
    # find patch
    base = stack.base_oid()
    name_found = None
    if base and oid == base:
        name_found = "{base}"
    else:
        for n, o in stack.patches.items():
            if o == oid:
                name_found = n; break
    if name_found is None:
        raise StgError(f"patch name not found for revision `{oid}`")
    if get_opt(parsed, "showbranch"):
        out_text(f"{stack.branch}:{name_found}\n")
    else:
        out_text(name_found + "\n")
