# ---------- branch ----------
def branch_display_list(repo):
    p = git(["for-each-ref", "--format=%(refname:short)", "refs/heads/"])
    branches = [ln.strip() for ln in p.stdout.decode(errors="surrogateescape").splitlines() if ln.strip()]
    cur = repo.branch
    maxlen = max((len(b) for b in branches), default=0)
    for b in branches:
        is_stack = repo.ref_oid(f"refs/stacks/{b}") is not None
        # protected
        pc = git(["config", f"branch.{b}.stgit.protect"])
        protected = pc.returncode == 0 and pc.stdout.decode().strip() == "true"
        prefix = (">" if b == cur else " ") + ("s" if is_stack else " ") + ("p" if protected else " ")
        desc_p = git(["config", f"branch.{b}.description"])
        desc = desc_p.stdout.decode().rstrip("\n") if desc_p.returncode == 0 else ""
        line = f"{prefix}\t{b:<{maxlen}} |"
        if desc:
            line += f" {desc}"
        out_text(line + "\n")
    return 0

