    if branch_name == "-" or re.match(r"^@\{-\d+\}$", branch_name):
        # resolve
        spec = "@{-1}" if branch_name == "-" else branch_name
        p = git(["rev-parse", "--symbolic-full-name", spec])
        if p.returncode != 0:
            raise StgError(f"branch `{orig_name}` not found")
        ref = p.stdout.decode().strip()
        if not ref.startswith("refs/heads/"):
            raise StgError(f"reference `{spec}` is not a local branch")
        branch_name = ref[len("refs/heads/"):]
    if repo.ref_oid(f"refs/heads/{branch_name}") is None:
        raise StgError(f"branch `{branch_name}` not found")
