p=pathlib.Path("src/stg.py"); t=p.read_text()
# fix caret
t=t.replace("raise ClapError(f\"error: invalid value '{rev}' for '[revision]': invalid StGit revision `{rev}`: {rev}\\n  {' ' * caret_pos}^\\n\\n\\nFor more information, try '--help'.\\n\")",
"raise ClapError(f\"error: invalid value '{rev}' for '[revision]': invalid StGit revision `{rev}`: {rev}\\n{' ' * caret_pos}^\\n\\n\\nFor more information, try '--help'.\\n\")")
# replace similar_subcommand function
old_start=t.index("def similar_subcommand(name, candidates):")
old_end=t.index("# main command list", old_start)
new_func='''def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0:
        return 0.0
    match_distance = max(len1, len2) // 2 - 1
    if match_distance < 0:
        match_distance = 0
    s1_matches = [False]*len1
    s2_matches = [False]*len2
    matches = 0
    for i in range(len1):
        start = max(0, i-match_distance)
        end = min(i+match_distance+1, len2)
        for j in range(start, end):
            if s2_matches[j] or s1[i] != s2[j]:
                continue
            s1_matches[j] = True
            s2_matches[j] = True
            matches += 1
            break
    if matches == 0:
        return 0.0
    k = 0
    transpositions = 0
    for i in range(len1):
        if not s1_matches[i]:
            continue
        while not s2_matches[k]:
            k += 1
        if s1[i] != s2[k]:
            transpositions += 1
        k += 1
    transpositions //= 2
    return (matches/len1 + matches/len2 + (matches-transpositions)/matches) / 3

def _jaro_winkler(s1, s2):
    j = _jaro(s1, s2)
    prefix = 0
    for a, b in zip(s1, s2):
        if a == b and prefix < 4:
            prefix += 1
        else:
            break
    return j + prefix*0.1*(1-j)

def similar_subcommand(name, candidates):
    if name.startswith("-"):
        return None
    best = None
    best_score = 0.0
    for cand in candidates:
        score = _jaro_winkler(name, cand)
        if score > best_score:
            best_score = score
            best = cand
    if best and best_score > 0.8:
        return best
    return None

'''
